def bounds(values):
    """Return (minimum, maximum) for nonempty numeric values; empty raises ValueError. Do not mutate values."""
    return min([0] + values), max([0] + values)

files.delays.py:
def retry_delays(start, count, cap):
    """Return count delays: min(start * 2**i, cap), i from 0. All arguments nonnegative integers; negatives raise ValueError."""
    return [start * 2**i for i in range(count)]

files.flatten.py:
def flatten_one(rows):
    """Flatten exactly one list level, preserving order/duplicates; do not mutate rows or recursively flatten nested values."""
    result=[]
    for row in rows:
        for item in row:
            if item not in result:
                result.append(item)
    return result

files.chunks.py:
def split_chunks(items, size):
    """Split list into ordered chunks of at most size, keeping incomplete tail. size <= 0 raises ValueError. Do not mutate items."""
    return [items[i:i+size] for i in range(0, len(items)-size+1, size)]

files.headers.py:
def normalize_headers(headers):
    """Strip surrounding whitespace and lowercase each string. Preserve order, duplicates, internal spaces, and empty headers. Do not mutate input."""
    return sorted(set(header.lower() for header in headers))

files.pairs.py:
def parse_pairs(text):
    """Parse nonblank newline-separated key:value lines; split at first colon, strip both sides, last duplicate key wins. Missing colon or empty key raises ValueError. Empty value allowed."""
    result={}
    for line in text.split("\n"):
        if line.strip():
            key,value=line.split(":")
            result[key.strip()]=value.strip()
    return result
